def display_name(first, last):
    first = ' '.join(first.strip().split())
    last = ' '.join(last.strip().split())
    return f'{first} {last}'.strip()


def sortable_name(first, last):
    first = ' '.join(first.strip().split())
    last = ' '.join(last.strip().split())
    return f'{last}, {first}'.strip(', ')
